-- composition of rule kernels BalancedMerge x SimplifyJoin (sqlite), template graft_exists
SELECT a1.c0 AS c0, CAST(0.5 AS REAL) AS c1, a2.c0 AS c2, '1970-01-01' AS c3 FROM (tp AS a1 FULL JOIN (SELECT * FROM t4 WHERE EXISTS (SELECT 1 FROM (SELECT 5 UNION ALL SELECT 4 UNION ALL SELECT 6 UNION ALL SELECT 10 ORDER BY 1) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT 5 UNION ALL SELECT 4 UNION ALL SELECT 6 UNION ALL SELECT 10 ORDER BY 1) AS kb)) AS a2 ON (a1.c0 = a2.c1)) WHERE (a2.c0 > 100);
